package ai.eva.android.probe;
import android.app.Instrumentation;import android.os.Bundle;import android.content.Context;import org.json.*;import java.io.*;import java.util.*;import java.util.concurrent.TimeUnit;import java.nio.file.Files;
/** Actual private-runtime, editable-template, renderer and API-only skill discovery acceptance. */
public final class RuntimeAuthoringCheck extends Instrumentation {
 public void onCreate(Bundle b){super.onCreate(b);start();}
 JSONObject run(String action)throws Exception{Context c=getTargetContext();ProcessBuilder builder=OfficeRuntime.process(c,action);LinuxRuntime.configure(c,builder);int count=Collections.frequency(builder.command(),"--link2symlink");LinuxRuntime.configure(c,builder);if(count!=1||Collections.frequency(builder.command(),"--link2symlink")!=1||Collections.frequency(builder.command(),"--sysvipc")!=1)throw new Exception("runtime configuration not idempotent");Process process=LinuxRuntime.start(c,builder);StringBuilder output=new StringBuilder();Thread reader=new Thread(()->{try(BufferedReader in=new BufferedReader(new InputStreamReader(process.getInputStream(),"UTF-8"))){String line;while((line=in.readLine())!=null)if(output.length()<200000)output.append(line).append('\n');}catch(Exception ignored){}});reader.start();if(!process.waitFor(200,TimeUnit.SECONDS)){process.destroyForcibly();throw new Exception("runtime check timeout");}reader.join(3000);if(process.exitValue()!=0)throw new Exception(output.toString());JSONObject result=null;for(String line:output.toString().split("\n"))try{result=new JSONObject(line);}catch(Exception ignored){}if(result==null||result.has("error"))throw new Exception(output.toString());return result;}
 public void onStart(){Bundle out=new Bundle();int code=0;JSONObject result=new JSONObject();try{Context c=getTargetContext();OfficeRuntime.deploy(c);long revision=OfficeRuntime.skillsRevision;OfficeRuntime.deploy(c);if(revision!=OfficeRuntime.skillsRevision)throw new Exception("managed skills rewritten without changes");JSONObject runtime=run("runtime-status");if(!runtime.optBoolean("hardlinks"))throw new Exception("hardlink preflight");result.put("runtime",runtime);JSONObject renderer=run("render-status");for(String name:new String[]{"office","pdf","pages","html"})if(!renderer.getJSONObject(name).optBoolean("ready"))throw new Exception("renderer unavailable: "+name);result.put("renderers",renderer);JSONObject sample=run("render-selftest");if(!sample.optBoolean("passed")||sample.optInt("renderedPages")!=4||!sample.optBoolean("editable"))throw new Exception("editable render sample");result.put("sample",sample);
 KernelHost host=KernelHost.api(c);synchronized(host.startup){host.ensureStarted();}JSONObject skills=host.rpc("skills/list",new JSONObject().put("cwds",new JSONArray().put("/root/eva-workspace")).put("forceReload",true));Set<String> names=new HashSet<>();JSONArray groups=skills.getJSONArray("data");for(int i=0;i<groups.length();i++){JSONArray rows=groups.getJSONObject(i).getJSONArray("skills");for(int j=0;j<rows.length();j++)names.add(rows.getJSONObject(j).getString("name"));}if(!names.contains("eva-ppt")||!names.contains("eva-capabilities"))throw new Exception("local skills not discovered by API-only kernel");File manifest=new File(c.getFilesDir(),"alpine/root/.eva-codex/android-models.json");if(manifest.isFile()){JSONArray models=new JSONObject(new String(Files.readAllBytes(manifest.toPath()),"UTF-8")).getJSONArray("models");for(int i=0;i<models.length();i++){JSONObject model=models.getJSONObject(i);if(model.optString("slug").equals("deepseek-flash")){if(!model.getJSONArray("input_modalities").toString().contains("image")||!model.optBoolean("supports_image_detail_original"))throw new Exception("DeepSeek image capabilities lost");result.put("deepseekVision",true);}}}
 result.put("apiOnlyLocalSkills",new JSONArray(Arrays.asList("eva-ppt","eva-capabilities")));result.put("passed",true);out.putString("result","PASS native launcher, hardlinks, rendering, editable templates and account-independent local skill discovery");}catch(Exception e){code=1;try{result.put("error",e.toString());}catch(Exception ignored){}out.putString("error",e.toString());}try{Files.write(new File(getTargetContext().getFilesDir(),"runtime-authoring-check.json").toPath(),result.toString(2).getBytes("UTF-8"));}catch(Exception e){code=1;out.putString("saveError",e.toString());}finish(code,out);}
}
